"""Static triage only; group summons can select one card and require manual review."""
import hashlib,json,re,sqlite3
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/fresh-ccg-september';SCRIPTS=ROOT/'public/CCG Downloads/CCG_Scripts'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
roster=json.loads((OUT/'baseline-remote.json').read_text(encoding='utf-8'))['cards'];assert len(roster)==711
rows=[]
with sqlite3.connect(f'file:{OUT / "current-spec-CCG_v1.db"}?mode=ro',uri=True) as db:
 for card in roster:
  code=card['passcode'];p=SCRIPTS/f'c{code}.lua';body=p.read_text(encoding='utf-8')
  markers=[{'line':i,'source':line.strip()} for i,line in enumerate(body.splitlines(),1) if 'SpecialSummonStep' in line or ('SpecialSummon(' in line and any(w in body for w in ['GetClassCount','SelectUnselectGroup','59822133','SelectMatchingCard','GetMatchingGroup']))]
  if not markers:continue
  name,desc=db.execute('select name,desc from texts where id=?',(code,)).fetchone()
  rows.append({'passcode':code,'name':name,'script_sha256':sha(p),'has_spirit_marker':'59822133' in body,'has_count_api_guard':'IsPlayerCanSpecialSummonCount' in body,'step_calls':body.count('SpecialSummonStep('),'printed_effect':desc,'calls':markers,'status':'OPEN: resolve group size, optional single summon and targeting/resolution guards manually'})
priority=[]
for row in rows:
 flags=[]
 if row['step_calls']>1:flags.append('multiple-step-call-sites')
 if re.search(r'Special Summon (?:up to |exactly )?[2-9]|Special Summon as many|Special Summon both',row['printed_effect'],re.I):flags.append('printed-multiple-summon-clause')
 if flags:priority.append({'passcode':row['passcode'],'signals':flags,'has_spirit_marker':row['has_spirit_marker'],'has_count_api_guard':row['has_count_api_guard']})
report={'scope':'All711 current sources scanned; deliberately broad group/step summon triage. No automatic defect or full audit claim. Spirit marker presence alone does not prove guard coverage.','scripts_scanned':711,'candidate_cards':len(rows),'priority_candidates':priority,'source_dependencies_sha256':{f'public/CCG Downloads/CCG_Scripts/c{c["passcode"]}.lua':sha(SCRIPTS/f'c{c["passcode"]}.lua') for c in roster},'database_sha256':sha(OUT/'current-spec-CCG_v1.db'),'roster_sha256':sha(OUT/'baseline-remote.json'),'scanner_sha256':sha(Path(__file__)),'cards':rows,'reviewed_notes':{'230998543':'Actual overlay/detach cost plus explicit EVENT_TO_GRAVE adapter exercises canonical previous-overlay/reason/host condition, reveal and pair. Missing Spirit guard repaired targeting/resolution; original legacy event native Omega remains open.','259783008':'Caudina summons exactly one (SelectMatchingCard 1,1); its two-card clause sends to GY. Static false positive only, not effect certification.','259177849':'Grand Blue Princess revives exactly one (Select 1,1); two materials refer to Fusion procedure. Static false positive only.','238276575':'Sylvan Greetings summon selects exactly one; two-card clause concerns excavation recovery. Static false positive only.','259024242':'Devotee repaired: targeting/resolution Spirit guards; actual two-token summon and Pyro cost, wrong-race/zone checks and old guard control in current-devotee-spirit-limit-batch.json.','259247853':'Machina restriction repaired at targeting/resolution; actual Extra Link pair/Spirit/name cases pass with isolated card-data and bounded selection adapters. General legacy group selection and proper initial source/anchor procedures remain open.','259635008':'Abe repaired after mandatory return: Spirit blocks pair revival while return remains; three actual End Phase scenarios/old guard control. Proper Synchro/other effects remain open.','259072745':'Bhodi optional revival capped at one under Spirit; three cases/control verified with explicit legacy IsFaceupEx adapter and Fusion-type fixture. Proper material Fusion and native Omega remain open.','259090287':'Dream Bedroom repaired: optional group cap one under Spirit while preserving excavation/decline; protection condition uses handler controller. Three actual scenarios/two old-code controls verified.','241543138':'Actual runtime found count API alone does not block Spirit. Added specific Spirit guards at targeting/resolution, retaining count API; three token/Spirit/zone cases and old guard control verified.','247755869':'Murugan repaired: Hand double summon blocked under Spirit at targeting/resolution; field single revival preserved. Four native public-core cases and old guard control in current-murugan-spirit-limit-batch.json.','259780273':'Carcel restriction repaired at targeting/resolution. Actual reveal cost/relation and pair verified with four cases/old guard control; prior history, oath probes and material effect remain open.','259481543':'Installed restriction repair with bounded two-card selection evidence; generic legacy selection helper unresolved.','259790247':'Installed restriction repair with actual canonical double summon evidence.'}}
(OUT/'simultaneous-summon-inventory.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'scanned':711,'candidates':len(rows),'with_spirit_marker':sum(r['has_spirit_marker'] for r in rows),'with_count_api_guard':sum(r['has_count_api_guard'] for r in rows)}))
